UPDATE public.proposal_templates
SET blocks = jsonb_set(
  blocks,
  '{1,html}',
  to_jsonb('<div style="box-sizing:border-box;width:100%;max-width:900px;aspect-ratio:16/9;margin:0 auto;padding:48px;border-radius:16px;overflow:hidden;display:flex;flex-direction:column;justify-content:center;font-family:Inter,system-ui,sans-serif;background:#ffffff;color:#0f172a;"><div style="display:inline-block;background:#22c55e;color:#fff;padding:6px 14px;border-radius:999px;font-size:13px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;margin-bottom:14px;">Contexto</div><h2 style="font-size:30px;margin:0 0 14px;font-weight:800;color:#064e3b;">Cenários e Desafios</h2><p style="font-size:14px;line-height:1.55;color:#334155;margin:0 0 10px;">O mercado de vendas públicas exige velocidade, organização e capacidade de acompanhamento constante. Empresas que atuam em licitações precisam lidar diariamente com grande volume de oportunidades, múltiplas fontes de informação, prazos críticos, documentos, concorrência e processos operacionais descentralizados.</p><p style="font-size:14px;line-height:1.55;color:#334155;margin:0 0 16px;">Na prática, esse cenário frequentemente gera excesso operacional, baixa previsibilidade, perda de oportunidades e dificuldade na consolidação das informações necessárias para uma gestão mais estratégica da operação.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;"><div style="background:#f0fdf4;border-left:4px solid #22c55e;padding:10px 14px;border-radius:8px;"><div style="font-weight:700;margin-bottom:2px;font-size:13px;">Volume de editais</div><div style="font-size:12px;color:#475569;">Milhares de oportunidades diárias dispersas em múltiplos portais.</div></div><div style="background:#f0fdf4;border-left:4px solid #22c55e;padding:10px 14px;border-radius:8px;"><div style="font-weight:700;margin-bottom:2px;font-size:13px;">Análise manual lenta</div><div style="font-size:12px;color:#475569;">Equipe consome horas filtrando, lendo e qualificando editais.</div></div><div style="background:#f0fdf4;border-left:4px solid #22c55e;padding:10px 14px;border-radius:8px;"><div style="font-weight:700;margin-bottom:2px;font-size:13px;">Perda de prazos</div><div style="font-size:12px;color:#475569;">Oportunidades estratégicas escapam por falhas de monitoramento.</div></div><div style="background:#f0fdf4;border-left:4px solid #22c55e;padding:10px 14px;border-radius:8px;"><div style="font-weight:700;margin-bottom:2px;font-size:13px;">Baixa taxa de conversão</div><div style="font-size:12px;color:#475569;">Falta de critério aumenta participações sem aderência real.</div></div></div></div>'::text)
)
WHERE id = '9ac64afe-2213-4ceb-89c0-1bad0b83df87';